mapper.sql:
AND p.status IN ('PUBLISHED', 'CLOSED')

  AND p.category = #{category}


  AND p.status = #{status}


  AND (p.title LIKE CONCAT('%', #{keyword}, '%') OR p.content LIKE CONCAT('%', #{keyword}, '%'))

AND EXISTS (
  SELECT 1
  FROM replies r
  WHERE r.post_id = p.id
    AND r.author_id = #{userId}
)

mapper.select:
SELECT p.*, up.nickname AS author_name FROM posts p LEFT JOIN user_profiles up ON up.user_id = p.author_id WHERE p.status IN ('PUBLISHED', 'CLOSED') AND p.id IN
#{id}
ORDER BY p.created_at DESC
